#include <gtest/gtest.h>

#include <string>
#include <vector>

#include "notifier.h"

class FakeMailer : public Mailer {
 public:
  bool send(const std::string& to, const std::string& body) override {
    sent.push_back(to);
    return next_result;
  }

  std::vector<std::string> sent;
  bool next_result = true;
};

TEST(NotifierTest, SendsToOwner) {
  FakeMailer mailer;
  Notifier notifier(mailer);
  notifier.notify_owner("build failed");
  ASSERT_EQ(mailer.sent.size(), 1u);
  EXPECT_EQ(mailer.sent[0], "owner@example.com");
}

TEST(NotifierTest, RetriesOnceOnFailure) {
  FakeMailer mailer;
  mailer.next_result = false;
  Notifier notifier(mailer);
  notifier.notify_owner("build failed");
  EXPECT_EQ(mailer.sent.size(), 2u);
}

