#include <gmock/gmock.h>
#include <gtest/gtest.h>

#include <string>

#include "notifier.h"

using ::testing::_;
using ::testing::Return;

class MockMailer : public Mailer {
 public:
  MOCK_METHOD(bool, send, (const std::string& to, const std::string& body), (override));
};

TEST(NotifierTest, SendsToOwner) {
  MockMailer mailer;
  EXPECT_CALL(mailer, send("owner@example.com", _)).WillOnce(Return(true));
  Notifier notifier(mailer);
  notifier.notify_owner("build failed");
}

TEST(NotifierTest, RetriesOnceOnFailure) {
  MockMailer mailer;
  EXPECT_CALL(mailer, send(_, _)).Times(2).WillOnce(Return(false));
  Notifier notifier(mailer);
  notifier.notify_owner("build failed");
}

TEST(NotifierTest, StopsAfterRetrySucceeds) {
  MockMailer mailer;
  EXPECT_CALL(mailer, send(_, _))
      .WillOnce(Return(false))
      .WillOnce(Return(true));
  Notifier notifier(mailer);
  notifier.notify_owner("build failed");
}
